import React, { useState, useMemo, useEffect } from "react";
import { useTable, useSortBy } from "react-table";
import axios from "axios";
import {
  FaEdit,
  FaTrashAlt,
  FaDownload,
  FaCheck,
  FaEye,
  FaTimes,
  FaArrowUp,
  FaArrowDown,
  FaPlus,
  FaFileImport,
  FaFileExport,
} from "react-icons/fa";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { Link, useNavigate } from "react-router-dom";
import Modal from "react-modal";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import UseAnimations from "react-useanimations";
import loading from "react-useanimations/lib/loading";

Modal.setAppElement("#root");

const LogotypesTable = () => {
  const [logotypes, setLogotypes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [heading, setHeading] = useState("");
  const [subheading, setSubheading] = useState("");
  const [selectedLogotype, setSelectedLogotype] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [pageIndex, setPageIndex] = useState(0);
  const [pageCount, setPageCount] = useState(0);
  const navigate = useNavigate();

  const pageSize = 5;

  const notify = () => {
    toast.success("Updated Successfully!");
  };

  const filteredLogotypes = useMemo(() => {
    return logotypes.filter((logotype) =>
      logotype.title.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [logotypes, searchTerm]);

  const columns = useMemo(
    () => [
      {
        Header: "ID",
        accessor: "autoIncrementId", // Display the auto-incremental ID
      },
      {
        Header: "Title",
        accessor: "title",
        Cell: ({ row }) => (
          <span
            className="hover:text-blue-500 cursor-pointer"
            onClick={() =>
              navigate(`/logotype/editLogotype/${row.original.id}`)
            }
          >
            {row.original.title}
          </span>
        ),
      },
      {
        Header: "Image",
        accessor: "photo",
        Cell: ({ value }) => {
          const firstImage =
            Array.isArray(value) && value.length > 0 ? value[0] : null;
          return firstImage ? (
            <img
              src={`/api/image/download/${firstImage}`}
              alt="Banner"
              className="w-32 h-20 object-cover"
            />
          ) : null;
        },
        disableSortBy: true,
      },
      {
        Header: "Options",
        Cell: ({ row }) => (
          <div className="flex gap-4">
            <button
              className="text-blue-500 hover:text-blue-700 transition"
              onClick={() => handleView(row.original)}
            >
              <FaEye />
            </button>
            <button className="text-blue-500 hover:text-blue-700 transition">
              <Link to={`/logotype/editLogotype/${row.original._id}`}>
                <FaEdit />
              </Link>
            </button>
            <button
              className="text-red-500 hover:text-red-700 transition"
              onClick={() => deleteLogotype(row.original._id)}
            >
              <FaTrashAlt />
            </button>
          </div>
        ),
        disableSortBy: true,
      },
    ],
    []
  );

  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } =
    useTable(
      {
        columns,
        data: filteredLogotypes,
      },
      useSortBy
    );

  const fetchLogotypes = async (pageIndex) => {
    setLoading(true);
    try {
      const response = await axios.get(
        `/api/logotype/getLogotype?page=${pageIndex + 1}`,
        {
          withCredentials: true,
        }
      );
      console.log(response.data); // Check the structure of the response
      const productsWithAutoIncrementId = response.data.data.map(
        (product, index) => ({
          ...product,
          autoIncrementId: pageIndex * pageSize + index + 1,
        })
      );
      setLogotypes(productsWithAutoIncrementId);
      setPageCount(Math.ceil(response.data.total / pageSize));
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const deleteLogotype = async (id) => {
    try {
      await axios.delete(`/api/logotype/deleteLogotype?id=${id}`, {
        withCredentials: true,
      });
      window.location.reload()
      fetchLogotypes();
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchLogotypes(pageIndex);
  }, [pageIndex]);

  const handleView = (logotype) => {
    setSelectedLogotype(logotype);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedLogotype(null);
  };

  const fetchHeadings = async () => {
    try {
      const response = await axios.get(
        "/api/pageHeading/heading?pageType=logotype",
        { withCredentials: true }
      );
      const { heading, subheading } = response.data;
      setHeading(heading || "");
      setSubheading(subheading || "");
    } catch (error) {
      console.error(error);
    }
  };

  const saveHeadings = async () => {
    try {
      await axios.put(
        "/api/pageHeading/updateHeading?pageType=logotype",
        {
          pagetype: "logotype",
          heading,
          subheading,
        },
        { withCredentials: true }
      );
      notify();
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchHeadings();
  }, []);

  const handleHeadingChange = (e) => setHeading(e.target.value);
  const handleSubheadingChange = (e) => setSubheading(e.target.value);

  return (
    <div className="p-4 overflow-x-auto">
      <ToastContainer />
      <div className="mb-8 border border-gray-200 shadow-lg p-4 rounded ">
        <div className="grid md:grid-cols-2  md:gap-2 grid-cols-1">
          <div className="mb-6">
            <label className="block text-gray-700 font-bold mb-2 uppercase font-serif">
              Heading
            </label>
            <input
              type="text"
              value={heading}
              onChange={handleHeadingChange}
              className="w-full px-4 py-2 border rounded-md focus:outline-none focus:border-blue-500 transition duration-300"
            />
          </div>
          <div className="mb-6">
            <label className="block text-gray-700 font-bold mb-2 uppercase font-serif">
              Sub heading
            </label>
            <input
              type="text"
              value={subheading}
              onChange={handleSubheadingChange}
              className="w-full px-4 py-2 border rounded-md focus:outline-none focus:border-blue-500 transition duration-300"
            />
          </div>
        </div>
        <button
          onClick={saveHeadings}
          className="px-4 py-2 bg-slate-700 text-white rounded hover:bg-slate-900 transition duration-300"
        >
          Save
        </button>
      </div>
      <div className="flex justify-between mb-4">
        <h1 className="text-xl font-bold text-gray-700 font-serif uppercase">
          Logotypes
        </h1>
        <Link
          to="/logotype/createLogotype"
          className="px-4 py-2 bg-slate-700 text-white rounded hover:bg-slate-900 transition duration-300"
        >
          <FaPlus size={15} />
        </Link>
      </div>
      <div className="mb-4">
        <input
          type="text"
          placeholder="Search by title..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full px-4 py-2 border rounded-md focus:outline-none focus:border-blue-500 transition duration-300"
        />
      </div>
      {loading ? (
        <div className="flex justify-center">
          <UseAnimations animation={loading} size={56} />
        </div>
      ) : (
        <>
          {logotypes.length === 0 ? (
            <div className="flex justify-center items-center">
              <p>No logotypes available.</p>
            </div>
          ) : (
            <table className="w-full mt-4 border-collapse" {...getTableProps()}>
              <thead className="bg-slate-700 hover:bg-slate-800 text-white">
                {headerGroups.map((headerGroup) => (
                  <tr {...headerGroup.getHeaderGroupProps()}>
                    {headerGroup.headers.map((column) => (
                      <th
                        {...column.getHeaderProps(
                          column.getSortByToggleProps()
                        )}
                        className="py-2 px-4 border-b border-gray-300 cursor-pointer uppercase font-serif"
                      >
                        <div className="flex items-center gap-2">
                          <span>{column.render("Header")}</span>
                          {column.canSort && (
                            <span className="ml-1">
                              {column.isSorted ? (
                                column.isSortedDesc ? (
                                  <FaArrowDown />
                                ) : (
                                  <FaArrowUp />
                                )
                              ) : (
                                <FaArrowDown className="text-gray-400" />
                              )}
                            </span>
                          )}
                        </div>
                      </th>
                    ))}
                  </tr>
                ))}
              </thead>
              <tbody {...getTableBodyProps()}>
                {rows.map((row) => {
                  prepareRow(row);
                  return (
                    <tr
                      {...row.getRowProps()}
                      className="border-b border-gray-300 hover:bg-gray-100 transition duration-150"
                    >
                      {row.cells.map((cell) => (
                        <td {...cell.getCellProps()} className="py-2 px-4">
                          {cell.render("Cell")}
                        </td>
                      ))}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </>
      )}
      <div className="mt-4 flex justify-center">
        <button
          onClick={() => setPageIndex(0)}
          disabled={pageIndex === 0}
          className="mr-2 px-3 py-1 bg-gray-300 rounded hover:bg-gray-400 transition"
        >
          {"<<"}
        </button>{" "}
        <button
          onClick={() => setPageIndex(pageIndex - 1)}
          disabled={pageIndex === 0}
          className="mr-2 px-3 py-1 bg-gray-300 rounded hover:bg-gray-400 transition"
        >
          {"<"}
        </button>{" "}
        <button
          onClick={() => setPageIndex(pageIndex + 1)}
          disabled={pageIndex + 1 >= pageCount}
          className="mr-2 px-3 py-1 bg-gray-300 rounded hover:bg-gray-400 transition"
        >
          {">"}
        </button>{" "}
        <button
          onClick={() => setPageIndex(pageCount - 1)}
          disabled={pageIndex + 1 >= pageCount}
          className="mr-2 px-3 py-1 bg-gray-300 rounded hover:bg-gray-400 transition"
        >
          {">>"}
        </button>{" "}
        <span>
          Page{" "}
          <strong>
            {pageIndex + 1} of {pageCount}
          </strong>{" "}
        </span>
      </div>
      <Modal
        isOpen={isModalOpen}
        onRequestClose={closeModal}
        contentLabel="Logotype Details"
        className="fixed inset-0 flex items-center justify-center bg-gray-800 bg-opacity-50"
      >
        <div className="bg-white p-8 rounded shadow-lg">
          <h2 className="text-xl font-bold">{selectedLogotype?.title}</h2>
          {selectedLogotype && (
            <img
              src={`/api/image/download/${selectedLogotype.image}`}
              alt={selectedLogotype.title}
              className="w-full h-auto mb-4"
            />
          )}
          <ReactQuill
            value={selectedLogotype?.description || ""}
            readOnly
            theme="bubble"
          />
          <button
            onClick={closeModal}
            className="mt-4 px-4 py-2 bg-gray-700 text-white rounded hover:bg-gray-900 transition duration-300"
          >
            Close
          </button>
        </div>
      </Modal>
    </div>
  );
};

export default LogotypesTable;
